import { useCallback, useEffect, useRef, useState, type ButtonHTMLAttributes, type ChangeEvent, type FormEvent, type ReactNode } from 'react';
import { NavLink, Route, Routes, useSearchParams } from 'react-router-dom';
import { Activity, ArrowDownToLine, ArrowRight, BookOpen, CalendarDays, Check, ChevronDown, CircleHelp, Clock3, Cloud, Headphones, Home, LibraryBig, Menu, Mic2, Plus, RotateCcw, Settings, Sparkles, Target, Upload, X } from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { days, weeks, seed, firstTwoWeekTasks, parseLectureImport, scheduleReview, getTodayDay, getScheduledDate, getDailyCoursePlan, lectureIsComplete, todayISO, mergeProgress, importUdemyCatalog, type AppData, type ReviewCard, type Lecture, type SkillId } from '../domain';
import { clearData, loadData, mergeBackupData, saveData } from '../persistence';
import { verifiedResources, isTrustedResourceUrl } from '../resources';
import { conversationScenarios, chatGPTVoicePrompt } from '../speaking';
import { skillRetention } from '../adaptive';
import { DailyPlan } from './DailyPlan';
import { nextPending } from '../guidedStudy';
import { allocateMinutes, dayPlanStatus, dailyTarget, makeDailyPlan } from '../studyPlan';
import { TutorPage } from './TutorPage';
import { StartupPage } from './StartupPage';
const cloudConfigured = Boolean(import.meta.env.VITE_SUPABASE_URL && import.meta.env.VITE_SUPABASE_ANON_KEY);

const icons = { '/': Home, '/hoje': Target, '/calendario': CalendarDays, '/udemy': BookOpen, '/input': Headphones, '/fala': Mic2, '/startup': Sparkles, '/tutor': Activity, '/revisao': RotateCcw, '/biblioteca': LibraryBig, '/avaliacoes': Activity, '/estatisticas': Sparkles, '/configuracoes': Settings };
const navItems = [
  { to: '/', label: 'Visão geral' }, { to: '/hoje', label: 'Hoje' }, { to: '/calendario', label: 'Calendário' }, { to: '/udemy', label: 'Udemy' },
  { to: '/input', label: 'Input' }, { to: '/fala', label: 'Conversação' }, { to: '/startup', label: 'Startup English' }, { to: '/tutor', label: 'AI English Tutor' }, { to: '/revisao', label: 'Revisão' }, { to: '/biblioteca', label: 'Biblioteca' },
  { to: '/avaliacoes', label: 'Avaliações' }, { to: '/estatisticas', label: 'Estatísticas' },
];
const formatDate = (value: string) => format(parseISO(value), "EEEE, d 'de' MMMM", { locale: ptBR });

export default function App() {
  const [data, setData] = useState<AppData | null>(null);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  useEffect(() => { void loadData().then(setData); }, []);
  const update = useCallback((fn: (current: AppData) => AppData) => setData((current) => {
    if (!current) return current;
    const next = fn(current); setSaving(true);
    void saveData(next).finally(() => setSaving(false)); return next;
  }), []);
  const showNotice = useCallback((message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 3600); }, []);
  if (!data) return <div className="loading-screen"><span className="spinner" /> Carregando seu plano local…</div>;
  const completedDays = days.filter((day) => dayPlanStatus(day.day, data, todayISO()) === 'completed').length;
  const doneActivityCount = Object.values(data.activities).filter((record) => record.status === 'done').length;
  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? 'open' : ''}`}>
      <div className="brand"><span className="brand-mark">e</span><div><b>english os</b><small>seu espaço de estudo</small></div><button className="icon-button close-menu" onClick={() => setMenuOpen(false)} aria-label="Fechar menu"><X size={18} /></button></div>
      <div className="side-label">APRENDIZADO</div>
      <nav aria-label="Navegação principal">{navItems.slice(0, 10).map((item) => { const Icon = icons[item.to as keyof typeof icons]; return <NavLink key={item.to} to={item.to} onClick={() => setMenuOpen(false)} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`} end={item.to === '/'}><Icon size={18} strokeWidth={1.8} /><span>{item.label}</span>{item.to === '/revisao' && dueCards(data).length > 0 && <i className="nav-dot" />}</NavLink>; })}</nav>
      <div className="side-label side-label-bottom">ACOMPANHAMENTO</div><nav aria-label="Acompanhamento">{navItems.slice(10).map((item) => { const Icon = icons[item.to as keyof typeof icons]; return <NavLink key={item.to} to={item.to} onClick={() => setMenuOpen(false)} className={({ isActive }) => `nav-link ${isActive ? 'active' : ''}`}><Icon size={18} strokeWidth={1.8} /><span>{item.label}</span></NavLink>; })}</nav>
      <div className="sidebar-bottom"><div className="cloud-status"><span className={`status-led ${cloudConfigured ? 'cloud' : ''}`} /><span>{cloudConfigured ? 'Supabase disponível' : 'Modo local'}</span></div><NavLink to="/configuracoes" className="profile-link"><div className="avatar">V</div><div><b>Meu progresso</b><small>{completedDays} de 182 dias concluídos</small></div><ChevronDown size={15} /></NavLink></div>
    </aside>
    {menuOpen && <button aria-label="Fechar navegação" className="scrim" onClick={() => setMenuOpen(false)} />}
    <main className="main-column">
      <header className="topbar"><button className="icon-button menu-toggle" aria-label="Abrir menu" onClick={() => setMenuOpen(true)}><Menu size={20} /></button><div className="breadcrumb">English OS <span>/</span> <b>Estude no seu ritmo</b></div><div className="topbar-right"><span className="save-state"><span className="status-led" />{saving ? 'Salvando…' : 'Salvo neste dispositivo'}</span><button className="icon-button help-button" aria-label="Ajuda" title="O progresso fica neste dispositivo por padrão"><CircleHelp size={19} /></button></div></header>
      <div className="page-wrap"><Routes>
        <Route path="/" element={<Dashboard data={data} />} />
        <Route path="/hoje" element={<Today data={data} update={update} showNotice={showNotice} />} />
        <Route path="/calendario" element={<Calendar data={data} update={update} />} />
        <Route path="/udemy" element={<Udemy data={data} update={update} showNotice={showNotice} />} />
        <Route path="/input" element={<InputPage data={data} update={update} />} />
        <Route path="/fala" element={<Speaking data={data} update={update} showNotice={showNotice} />} />
        <Route path="/startup" element={<StartupPage data={data} update={update} />} />
        <Route path="/tutor" element={<TutorPage data={data} update={update} />} />
        <Route path="/revisao" element={<Review data={data} update={update} />} />
        <Route path="/biblioteca" element={<Library />} />
        <Route path="/avaliacoes" element={<Assessments data={data} update={update} />} />
        <Route path="/estatisticas" element={<Statistics data={data} doneCount={doneActivityCount} completedDays={completedDays} />} />
        <Route path="/configuracoes" element={<SettingsPage data={data} update={update} showNotice={showNotice} />} />
        <Route path="*" element={<Dashboard data={data} />} />
      </Routes></div>
    </main>
    {notice && <div className="toast" role="status"><Check size={16} />{notice}</div>}
  </div>;
}

function dueCards(data: AppData) { const today = todayISO(); return data.cards.filter((card) => card.dueDate <= today); }
function PageHeading({ eyebrow, title, description, children }: { eyebrow: string; title: string; description: string; children?: ReactNode }) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{children && <div className="heading-actions">{children}</div>}</div>; }
function Button({ children, variant = 'primary', ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'secondary' | 'quiet' }) { return <button {...props} className={`button ${variant} ${props.className || ''}`}>{children}</button>; }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={`card ${className}`}>{children}</section>; }
function SectionTitle({ children, detail }: { children: ReactNode; detail?: ReactNode }) { return <div className="section-title"><h2>{children}</h2>{detail}</div>; }
function ProgressBar({ value }: { value: number }) { return <div className="progress-track"><span style={{ width: `${Math.max(0, Math.min(100, value))}%` }} /></div>; }
function Dashboard({ data }: { data: AppData }) {
  const today = getTodayDay(new Date(), data.settings.startDate); const due = dueCards(data);
  const sessionDay = data.studySession?.day && data.studySession.day >= 1 && data.studySession.day <= 182 ? data.studySession.day : today.day;
  const resumeDay = nextPending(makeDailyPlan(sessionDay, data), data) ? sessionDay : Math.min(182, sessionDay + 1);
  const heroDay = days[resumeDay - 1];
  const heroPlan = makeDailyPlan(resumeDay, data);
  const selected = data.studySession?.day === resumeDay && heroPlan.find((item) => item.key === data.studySession?.activityKey && !['done', 'skipped'].includes(data.activities[item.key]?.status || 'todo'));
  const heroActivity = selected || nextPending(heroPlan, data);
  const heroLink = `/hoje?dia=${heroDay.day}${heroActivity ? `&atividade=${encodeURIComponent(heroActivity.key)}` : ''}`;
  const completed = days.filter((day) => dayPlanStatus(day.day, data, todayISO()) === 'completed').length;
  const minutes = days.flatMap((day) => makeDailyPlan(day.day, data)).reduce((sum, task) => { const record = data.activities[task.key]; return sum + (record?.status === 'done' ? record.actualMinutes ?? task.minutes : 0); }, 0);
  const currentWeekDays = days.slice(Math.floor((today.day - 1) / 7) * 7, Math.floor((today.day - 1) / 7) * 7 + 7);
  const weekPlan = currentWeekDays.reduce((sum, day) => sum + dailyTarget(day, data), 0);
  const weekDone = currentWeekDays.reduce((sum, day) => sum + makeDailyPlan(day.day, data).reduce((taskSum, task) => taskSum + (data.activities[task.key]?.status === 'done' ? (data.activities[task.key]?.actualMinutes || task.minutes) : 0), 0), 0);
  const nextLecture = data.lectures.find((lecture) => !lectureIsComplete(lecture, data));
  return <>
    <PageHeading eyebrow={format(new Date(), 'EEEE, d MMMM', { locale: ptBR }).toLocaleUpperCase('pt-BR')} title="Olá, vamos estudar?" description="Abra sua próxima atividade e continue no seu ritmo." ><span className="date-pill"><span className="live-dot" /> Dia {today.day} de 182</span></PageHeading>
    <div className="dashboard-grid">
      <Card className="hero-card"><div className="hero-copy"><div className="eyebrow light">SEU PLANO · DIA {heroDay.day}</div><h2>{heroDay.weekly_theme}</h2><p>{heroDay.daily_output} — no seu ritmo, sem pular etapas.</p><div className="hero-meta"><span><CalendarDays size={15} /> {formatDate(getScheduledDate(heroDay.day, data))}</span><span><Clock3 size={15} /> {heroDay.minutes} min</span></div><NavLink className="button hero-button" to={heroLink}>{data.studySession && resumeDay === sessionDay ? 'CONTINUAR DE ONDE PAREI' : 'CONTINUAR ESTUDANDO'} <ArrowRight size={16} /></NavLink></div><div className="hero-illustration"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="planet">A<span>0</span></div><div className="spark spark-a">✳</div><div className="spark spark-b">✦</div><div className="orb-dot" /></div></Card>
      <Card className="progress-card"><div className="card-topline"><span>PROGRESSO DO PLANO</span><span className="subtle">26 semanas</span></div><div className="big-number">{completed}<span> / 182 dias</span></div><ProgressBar value={completed / 182 * 100} /><div className="progress-footer"><span>{Math.round(completed / 182 * 100)}% completo</span><span>Meta: A2 / B1*</span></div><div className="level-note">*Objetivo ambicioso de estudo; conclusão não certifica nível.</div></Card>
    </div>
    <div className="stats-row"><StatCard icon={<Clock3 size={18} />} label="Carga concluída (estimada)" value={`${(minutes / 60).toFixed(minutes % 60 ? 1 : 0)} h`} helper="duração planejada das atividades concluídas" /><StatCard icon={<Check size={18} />} label="Atividades feitas" value={String(Object.values(data.activities).filter((item) => item.status === 'done').length)} helper="desde o início" /><StatCard icon={<RotateCcw size={18} />} label="Revisões vencidas" value={String(due.length)} helper={due.length ? 'prontas para revisar' : 'tudo em dia'} accent={due.length > 0} /></div>
    <div className="content-grid"><Card><SectionTitle detail={<NavLink className="text-link" to="/calendario">Ver calendário <ArrowRight size={14} /></NavLink>}>Sua semana</SectionTitle><div className="week-strip">{currentWeekDays.map((day) => { const state = dayPlanStatus(day.day, data, todayISO()); const date = getScheduledDate(day.day, data); return <NavLink key={day.day} to={`/hoje?dia=${day.day}`} className={`week-day ${day.day === today.day ? 'today' : ''}`}><span>{format(parseISO(date), 'EEEEE', { locale: ptBR })}</span><b>{format(parseISO(date), 'd')}</b><i className={state === 'completed' ? 'done' : state === 'overdue' ? 'overdue' : ''}>{state === 'completed' ? '✓' : state === 'overdue' ? '!' : day.day % 7 === 0 ? '45m' : '·'}</i></NavLink>; })}</div><div className="week-target"><span><Target size={15} /> Meta semanal</span><b>{data.settings.targetMinutes * 6 + Math.min(data.settings.targetMinutes,45)} min</b></div><ProgressBar value={weekPlan ? Math.min(100, weekDone / weekPlan * 100) : 0} /><small className="subtle">{weekDone} de {weekPlan} minutos planejados registrados</small></Card>
      <Card className="next-card"><SectionTitle detail={<span className="subtle">{data.lectures.length === 545 ? `${data.courseTests?.length || 0} testes importados` : 'Catálogo parcial'}</span>}>Próximo passo</SectionTitle>{nextLecture ? <><div className="next-lecture"><div className="lecture-icon"><BookOpen size={21} /></div><div><span className="eyebrow">UDEMY · AULA {nextLecture.sequence}</span><b>{nextLecture.title}</b><small>{nextLecture.durationMinutes} min · {nextLecture.type}</small></div></div><NavLink className="text-link" to="/udemy">Abrir acompanhamento <ArrowRight size={14} /></NavLink></> : <><p className="empty-copy">Todas as aulas estão concluídas na origem ou marcadas no English OS.</p><NavLink className="text-link" to="/udemy">Ver catálogo e testes <ArrowRight size={14} /></NavLink></>}</Card></div>
    <div className="bottom-note"><span className="note-icon"><Sparkles size={16} /></span><p>Você começa com <b>“{weeks[0].focus}”</b>. O objetivo de hoje é pequeno e concreto: {today.daily_output.toLocaleLowerCase()}.</p><NavLink to="/hoje">Ver plano <ArrowRight size={14} /></NavLink></div>
  </>;
}
function StatCard({ icon, label, value, helper, accent = false }: { icon: ReactNode; label: string; value: string; helper: string; accent?: boolean }) { return <Card className={`stat-card ${accent ? 'stat-accent' : ''}`}><div className="stat-icon">{icon}</div><span className="stat-label">{label}</span><b>{value}</b><small>{helper}</small></Card>; }

function Today({ data, update, showNotice }: { data: AppData; update: (fn: (current: AppData) => AppData) => void; showNotice: (message: string) => void }) {
  const [searchParams, setSearchParams] = useSearchParams();
  const todayNumber = getTodayDay(new Date(), data.settings.startDate).day;
  const [selectedDay, setSelectedDay] = useState(Math.max(1, Math.min(182, Number(searchParams.get('dia')) || data.studySession?.day || todayNumber)));
  const [notes, setNotes] = useState(data.dayNotes[selectedDay] || '');
  const day = days.find((candidate) => candidate.day === selectedDay)!;
  const scheduledDate = getScheduledDate(day.day, data);
  const explicit = firstTwoWeekTasks[day.week];
  const coursePlan = getDailyCoursePlan(day.day, data, allocateMinutes(dailyTarget(day, data))[0]);
  useEffect(() => { setNotes(data.dayNotes[selectedDay] || ''); }, [selectedDay, data.dayNotes]);
  useEffect(() => {
    const dayParam = Number(searchParams.get('dia'));
    if (dayParam >= 1 && dayParam <= 182 && dayParam !== selectedDay) setSelectedDay(dayParam);
    const requested = searchParams.get('atividade');
    if (requested && dayParam >= 1 && dayParam <= 182 && requested.startsWith(`${dayParam}:`)) {
      update((current) => ({ ...current, studySession: { day: dayParam, activityKey: requested, open: true } }));
      setSearchParams({ dia: String(dayParam) }, { replace: true });
    }
  }, [searchParams, selectedDay, setSearchParams, update]);
  const selectDay = (number: number) => { const next = Math.max(1, Math.min(182, number)); setSelectedDay(next); setSearchParams({ dia: String(next) }); };
  return <><PageHeading eyebrow="SEU PLANO DE ESTUDO" title="Estudo de hoje" description="Siga as etapas na ordem que fizer sentido. Você pode pausar e continuar depois."><div className="day-switcher"><button aria-label="Dia anterior" onClick={() => selectDay(selectedDay - 1)}>‹</button><span>Dia {day.day} <small>de 182</small></span><button aria-label="Próximo dia" onClick={() => selectDay(selectedDay + 1)}>›</button></div></PageHeading>
    <div className="today-overview"><div className="today-date"><CalendarDays size={18} /><span>{formatDate(scheduledDate)}<small>Semana {day.week} · {day.cefr_target}{data.overrides[day.day] ? ' · reagendado' : ''}</small></span></div><div className="today-focus"><b>{day.weekly_theme}</b><span>{day.daily_output}</span></div><div className="today-duration"><Clock3 size={17} /><b>{dailyTarget(day, data)} min</b></div></div>
    <div className="today-columns"><div><DailyPlan dayNumber={day.day} currentDayNumber={todayNumber} data={data} update={update} showNotice={showNotice} />
      <CourseDailyQueue data={data} update={update} coursePlan={coursePlan} />
      {explicit && <Card className="micro-card"><SectionTitle detail={<span className="micro-badge">PRÁTICA GUIADA</span>}>Entregáveis concretos · primeiros 14 dias</SectionTitle><p>Exercícios explícitos para apoiar a lista de tarefas do plano original.</p>{explicit.map((item) => <div className="micro-task" key={item.key}><div className="micro-check"><Check size={13} /></div><div><b>{item.title}</b><p>{item.instruction}</p><blockquote>{item.sample}</blockquote></div><span>{item.minutes} min</span></div>)}</Card>}
      <Card><SectionTitle>Registro desta sessão</SectionTitle><label className="field-label" htmlFor="session-note">O que ficou fácil ou difícil?</label><textarea id="session-note" value={notes} onChange={(event) => setNotes(event.target.value)} onBlur={() => update((current) => ({ ...current, dayNotes: { ...current.dayNotes, [selectedDay]: notes } }))} placeholder="Anote uma palavra nova, dúvida ou pequena conquista…" rows={3} /></Card></div>
      <div className="today-aside"><Card className="output-card"><div className="output-icon"><Target size={20} /></div><span className="eyebrow">ENTREGÁVEL DO DIA</span><h3>{day.daily_output}</h3><p>Objetivo da semana: {day.weekly_output}.</p></Card><Card className="udemy-callout"><span className="eyebrow">SEU CURSO</span><h3>{data.lectures.length} aulas · {data.courseTests?.length || 0} testes</h3><p>Conclusões da origem e marcações locais são exibidas separadas.</p><NavLink className="text-link" to="/udemy">Ver aulas e testes <ArrowRight size={14} /></NavLink></Card><Card className="review-callout"><div className="review-head"><span className="review-icon"><RotateCcw size={17} /></span><span className="eyebrow">REVISÃO ESPAÇADA</span></div><h3>{dueCards(data).length ? `${dueCards(data).length} cartões vencidos` : 'Sua fila está vazia'}</h3><p>Cartões próprios com agendamento D+1, D+3, D+7, D+14 e D+30.</p><NavLink className="text-link" to="/revisao">Abrir revisão <ArrowRight size={14} /></NavLink></Card><div className="source-note"><CircleHelp size={15} /><span>O nível A2/B1 é uma meta ambiciosa, não uma promessa ou certificação.</span></div></div></div>
  </>;
}
function Calendar({ data, update }: { data: AppData; update: (fn: (current: AppData) => AppData) => void }) {
  const [selectedWeek, setSelectedWeek] = useState(1); const selected = weeks[selectedWeek - 1];
  return <>
    <PageHeading eyebrow="SEU CAMINHO" title="Calendário de 182 dias" description="Reagende uma data sem alterar o tema ou apagar o histórico. Pendências continuam disponíveis para retomada." />
    <div className="calendar-summary"><div><b>{format(parseISO(getScheduledDate(1, data)), 'd MMM yyyy', { locale: ptBR })}</b><span>Início planejado</span></div><ArrowRight size={18} /><div><b>{format(parseISO(getScheduledDate(182, data)), 'd MMM yyyy', { locale: ptBR })}</b><span>Último dia planejado</span></div><div className="timezone-pill">{seed.metadata.timezone}</div></div>
    <div className="calendar-layout"><div className="week-list">{weeks.map((week) => { const weekDays = days.slice((week.week - 1) * 7, week.week * 7); const done = weekDays.filter((day) => dayPlanStatus(day.day, data, todayISO()) === 'completed').length; const overdue = weekDays.filter((day) => dayPlanStatus(day.day, data, todayISO()) === 'overdue').length; return <button className={`week-row ${selectedWeek === week.week ? 'selected' : ''}`} key={week.week} onClick={() => setSelectedWeek(week.week)}><span className="week-index">{String(week.week).padStart(2, '0')}</span><span className="week-info"><b>{week.theme}</b><small>{format(parseISO(getScheduledDate(weekDays[0].day, data)), 'd MMM', { locale: ptBR })} – {format(parseISO(getScheduledDate(weekDays.at(-1)!.day, data)), 'd MMM', { locale: ptBR })} · {week.level}{overdue ? ` · ${overdue} atrasados` : ''}</small></span><span className="week-mini-progress">{done}/7</span></button>; })}</div>
      <Card className="selected-week-card"><div className="card-topline"><span>SEMANA {String(selected.week).padStart(2, '0')}</span><span className="level-pill">{selected.level}</span></div><h2>{selected.theme}</h2><p>{selected.focus}</p><div className="week-outcome"><span>AO FINAL DA SEMANA</span><b>{selected.outcome}</b></div>
        <div className="calendar-days">{days.slice((selectedWeek - 1) * 7, selectedWeek * 7).map((day) => { const state = dayPlanStatus(day.day, data, todayISO()); const planned = getScheduledDate(day.day, data); return <div className={`calendar-day ${state}`} key={day.day}><div className="calendar-day-head"><b>Dia {day.day}</b><span>{format(parseISO(planned), 'EEE, d MMM', { locale: ptBR })}</span><StatusBadge state={state} /></div><p>{day.daily_mode} · {dailyTarget(day, data)} min</p><small>{day.daily_output}</small><div className="calendar-day-actions"><label htmlFor={`date-${day.day}`}>Data</label><input id={`date-${day.day}`} aria-label={`Reagendar dia ${day.day}`} type="date" value={planned} onChange={(event) => { const value = event.target.value; update((current) => { const overrides = { ...current.overrides }; const original = getScheduledDate(day.day, { ...current, overrides: {} }); const fromDate = getScheduledDate(day.day, current); if (value === original) delete overrides[day.day]; else if (value) overrides[day.day] = value; const toDate = getScheduledDate(day.day, { ...current, overrides }); if (fromDate === toDate) return current; const now = new Date().toISOString(); const activities = { ...current.activities }; const history = [...(current.activityHistory || [])]; for (let index = 0; index < 8; index++) { const key = `${day.day}:${index}`; const old = activities[key]; if (old?.status === 'done' || old?.status === 'skipped') continue; activities[key] = { ...(old || { status: 'todo' as const, updatedAt: now }), lifecycle: 'rescheduled', scheduledDate: toDate, updatedAt: now }; history.push({ id: crypto.randomUUID(), activityKey: key, day: day.day, kind: 'rescheduled', at: now, fromDate, toDate }); } return { ...current, overrides, activities, activityHistory: history }; }); }} /><NavLink className="text-link" to={`/hoje?dia=${day.day}`}>Retomar dia <ArrowRight size={12} /></NavLink></div></div>; })}</div>
      </Card></div>
  </>;
}
function StatusBadge({ state }: { state: string }) { const label: Record<string, string> = { 'not-started': 'Não iniciado', 'in-progress': 'Em andamento', completed: 'Concluído', skipped: 'Dispensado', overdue: 'Atrasado', rescheduled: 'Reagendado' }; return <span className={`status-badge status-${state}`}>{label[state] || state}</span>; }

function CourseDailyQueue({ data, update, coursePlan }: { data: AppData; update: (fn: (current: AppData) => AppData) => void; coursePlan: ReturnType<typeof getDailyCoursePlan> }) {
  const toggleLecture = (lecture: Lecture) => update((current) => {
    const isDone = lecture.status === 'watched' || current.watched.includes(lecture.id);
    const status = isDone ? 'not-started' as const : 'watched' as const;
    return { ...current, lectures: current.lectures.map((item) => item.id === lecture.id ? { ...item, status, completedAt: status === 'watched' ? new Date().toISOString() : undefined } : item), watched: status === 'watched' ? [...new Set([...current.watched, lecture.id])] : current.watched.filter((id) => id !== lecture.id) };
  });
  const toggleTest = (testId: string) => update((current) => ({ ...current, courseTests: (current.courseTests || []).map((test) => test.id === testId ? { ...test, status: test.status === 'completed' ? 'not-started' : 'completed', completedAt: test.status === 'completed' ? undefined : new Date().toISOString() } : test) }));
  return <Card className="daily-course-queue"><SectionTitle detail={<span className="subtle">{coursePlan.budgetMinutes} min · fila adaptativa</span>}>Udemy para este dia</SectionTitle><p className="empty-copy">A fila segue a numeração original. Se você atrasar, os itens incompletos ficam no começo e a carga sugerida recalcula dentro do limite diário. O status da importação permanece separado do seu registro local.</p>{coursePlan.lessons.length ? <div className="daily-course-items">{coursePlan.lessons.map((lesson) => <div className="daily-course-row" key={lesson.id}><div className="daily-course-number">{lesson.sequence}</div><div className="daily-course-copy"><b>{lesson.title}</b><small>{lesson.durationMinutes} min · {lesson.type}{lesson.section ? ` · ${lesson.section}` : ' · seção não informada no catálogo'}</small><span className={`source-status source-${lesson.importedStatus}`}>Importação: {lesson.importedStatus === 'completed' ? 'concluída' : lesson.importedStatus === 'not_completed' ? 'não concluída' : 'status desconhecido'}</span></div><div className="daily-course-actions"><a href={seed.metadata.course_url} target="_blank" rel="noopener noreferrer">Abrir curso</a><button className="watch-button" onClick={() => toggleLecture(lesson)}>{lesson.status === 'watched' || data.watched.includes(lesson.id) ? 'Desfazer conclusão local' : 'Marcar aula concluída'}</button></div></div>)}</div> : <p className="empty-copy">{coursePlan.remainingLessons ? 'Hoje é um dia leve, sem bloco Udemy. A fila continua disponível no próximo dia de estudo.' : 'As 545 aulas estão concluídas na fonte ou marcadas neste app.'}</p>}{coursePlan.tests.length > 0 && <div className="daily-course-tests"><h3>Teste de compreensão recomendado</h3>{coursePlan.tests.map((test) => <div className="daily-course-row" key={test.id}><div className="daily-course-number">T{test.sequence}</div><div className="daily-course-copy"><b>{test.title}</b><small>Duração não informada no catálogo</small><span>A associação a uma aula específica não veio no arquivo; este teste é distribuído por ordem ao longo do plano.</span></div><div className="daily-course-actions"><a href={seed.metadata.course_url} target="_blank" rel="noopener noreferrer">Abrir curso</a><button className="watch-button" onClick={() => toggleTest(test.id)}>{test.status === 'completed' ? 'Desfazer teste concluído' : 'Marcar teste concluído'}</button></div></div>)}{coursePlan.overdueTests > 0 && <p className="subtle">{coursePlan.overdueTests} teste(s) anterior(es) aguardam registro e aparecem antes dos próximos.</p>}</div>}</Card>;
}

function Udemy({ data, update, showNotice }: { data: AppData; update: (fn: (current: AppData) => AppData) => void; showNotice: (message: string) => void }) {
  const inputRef = useRef<HTMLInputElement>(null); const [error, setError] = useState('');
  const addFiles = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { const text = await file.text(); const parsed: unknown = file.name.toLowerCase().endsWith('.json') ? JSON.parse(text) : undefined; if (parsed && typeof parsed === 'object' && 'lessons' in parsed) { update((current) => importUdemyCatalog(current, parsed)); showNotice('Catálogo de 545 aulas e 24 testes importado; conclusões locais preservadas.'); } else { const imported = parseLectureImport(text); update((current) => { const byId = new Map(current.lectures.map((item) => [item.id, item])); const bySequence = new Map(current.lectures.map((item) => [item.sequence, item])); for (const item of imported) { const previous = byId.get(item.id) || bySequence.get(item.sequence); if (previous && previous.id !== item.id) byId.delete(previous.id); byId.set(item.id, { ...previous, ...item, status: previous?.status ?? item.status, importedStatus: item.importedStatus ?? previous?.importedStatus }); } const lectures = [...byId.values()].sort((a, b) => a.sequence - b.sequence); return { ...current, lectures, watched: [...new Set([...current.watched, ...lectures.filter((item) => item.status === 'watched').map((item) => item.id)])] }; }); showNotice(`${imported.length} aula(s) atualizada(s); progresso preservado.`); } setError(''); } catch (issue) { setError(issue instanceof Error ? issue.message : 'Não foi possível ler esse arquivo.'); } event.target.value = ''; };
  const next = data.lectures.find((lecture) => !lectureIsComplete(lecture, data));
  const importedDone = data.lectures.filter((lecture) => lecture.importedStatus === 'completed').length;
  const appDone = data.lectures.filter((lecture) => lecture.status === 'watched' || data.watched.includes(lecture.id)).length;
  const totalMinutes = data.lectures.reduce((sum, item) => sum + (item.durationMinutes || 0), 0);
  const setLectureStatus = (lecture: Lecture) => update((current) => { const complete = lecture.status === 'watched' || current.watched.includes(lecture.id); const status = complete ? 'not-started' as const : 'watched' as const; return { ...current, lectures: current.lectures.map((item) => item.id === lecture.id ? { ...item, status, completedAt: status === 'watched' ? new Date().toISOString() : undefined } : item), watched: status === 'watched' ? [...new Set([...current.watched, lecture.id])] : current.watched.filter((id) => id !== lecture.id) }; });
  const courseTests = data.courseTests || [];
  return <><PageHeading eyebrow="CURSO EXTERNO" title="Seu curso na Udemy" description="Catálogo real importado do arquivo fornecido. Links individuais e IDs não vieram nesse arquivo; o acesso abre a página geral do curso."><Button variant="secondary" onClick={() => inputRef.current?.click()}><Upload size={15} /> Reimportar JSON / CSV</Button><input ref={inputRef} type="file" hidden accept=".csv,.json,text/csv,application/json" onChange={(event) => void addFiles(event)} /></PageHeading>
    <Card className="course-banner"><div className="course-icon"><BookOpen size={25} /></div><div className="course-copy"><span className="eyebrow">CURSO DO CATÁLOGO FORNECIDO</span><h2>{data.catalogImport?.courseTitle || 'Curso de Inglês Rápido'}</h2><p>{data.catalogImport?.source || 'Fonte informada no arquivo'} · status capturado: {data.catalogImport?.reportedProgress || 'sem informação'}</p><a className="text-link" href={seed.metadata.course_url} target="_blank" rel="noopener noreferrer">Abrir página geral do curso na Udemy <ArrowRight size={14} /></a></div><div className="course-facts"><div><b>{data.lectures.length}</b><span>de 545 aulas importadas</span></div><div><b>{courseTests.length}</b><span>de 24 testes importados</span></div></div></Card>{error && <div className="inline-error" role="alert">{error}</div>}
    <div className="udemy-stats"><StatCard icon={<BookOpen size={18} />} label="Duração catalogada" value={`${Math.floor(totalMinutes / 60)}h ${totalMinutes % 60}m`} helper="soma das durações fornecidas" /><StatCard icon={<Check size={18} />} label="Conclusões na origem" value={String(importedDone)} helper="15 segundo o estado copiado; histórico mantido" /><StatCard icon={<Check size={18} />} label="Conclusões neste app" value={String(appDone)} helper="marcações locais separadas da origem" /></div>
    <Card><SectionTitle detail={<span className="subtle">545 títulos em ordem · não há seções no arquivo</span>}>Fila de aulas</SectionTitle>{next && <div className="next-up"><div><span className="eyebrow">PRÓXIMO ITEM INCOMPLETO · Nº {next.sequence}</span><h3>{next.title}</h3><p>{next.durationMinutes} min · {next.type} · sequência original; sem link individual</p></div><a className="button primary" href={seed.metadata.course_url} target="_blank" rel="noopener noreferrer">Abrir curso <ArrowRight size={15} /></a></div>}<div className="lecture-list">{data.lectures.map((lecture) => { const appCompleted = lecture.status === 'watched' || data.watched.includes(lecture.id); return <div className={`lecture-row ${lectureIsComplete(lecture, data) ? 'watched' : ''}`} key={lecture.id}><span className="lecture-sequence">{lecture.sequence}</span><div className="lecture-info"><b>{lecture.title}</b><small>{lecture.durationMinutes} min · {lecture.type} · origem: {lecture.importedStatus === 'completed' ? 'concluída' : lecture.importedStatus === 'not_completed' ? 'não concluída' : 'desconhecida'}</small></div><button className={`watch-button ${appCompleted ? 'is-watched' : ''}`} aria-label={appCompleted ? `Desfazer conclusão local aula ${lecture.sequence}` : `Marcar aula ${lecture.sequence} concluída`} onClick={() => setLectureStatus(lecture)}>{appCompleted ? <><Check size={13} /> Concluída no app</> : 'Marcar no app'}</button></div>; })}</div><div className="integrity-note"><CircleHelp size={15} /><span>15 status “concluída”, 529 “não concluída” e 1 “desconhecido” são mantidos como dados importados. O registro local pode mudar sem sobrescrever essa fotografia original. Concluir não significa dominar; compreensão e exercícios continuam sendo avaliados separadamente.</span></div></Card>
    <Card><SectionTitle detail={<span className="subtle">Status não existia no arquivo; marque aqui após fazer cada teste</span>}>24 testes de compreensão</SectionTitle><div className="lecture-list">{courseTests.map((test) => <div className={`lecture-row ${test.status === 'completed' ? 'watched' : ''}`} key={test.id}><span className="lecture-sequence">T{test.sequence}</span><div className="lecture-info"><b>{test.title}</b><small>Duração não informada · teste da fonte Udemy</small></div><button className={`watch-button ${test.status === 'completed' ? 'is-watched' : ''}`} aria-label={test.status === 'completed' ? `Desfazer teste ${test.sequence}` : `Marcar teste ${test.sequence} concluído`} onClick={() => update((current) => ({ ...current, courseTests: (current.courseTests || []).map((item) => item.id === test.id ? { ...item, status: item.status === 'completed' ? 'not-started' : 'completed', completedAt: item.status === 'completed' ? undefined : new Date().toISOString() } : item) }))}>{test.status === 'completed' ? 'Teste concluído' : 'Marcar teste concluído'}</button></div>)}</div></Card>
    <div className="footnote">Importação local persistente, repetível sem duplicar aulas/testes; cada reimportação mantém seu status local. Udemy não fornece link individual nem integração de progresso neste catálogo.</div>
  </>;
}

function InputPage({ data, update }: { data: AppData; update: (fn: (current: AppData) => AppData) => void }) {
  const [level, setLevel] = useState('Todos'); const [skill, setSkill] = useState('Todas'); const [topic, setTopic] = useState('Todos');
  const resources = verifiedResources.filter((item) => (level === 'Todos' || item.level === level) && (skill === 'Todas' || item.skill === skill) && (topic === 'Todos' || item.topic === topic));
  const setState = (id: string, field: 'watched' | 'understood' | 'repeat', value: boolean) => update((current) => { const previous = current.inputProgress?.[id] || { watched: false, understood: false, repeat: false, updatedAt: '' }; return { ...current, inputProgress: { ...(current.inputProgress || {}), [id]: { ...previous, [field]: value, updatedAt: new Date().toISOString() } } }; });
  return <><PageHeading eyebrow="ESCUTA E LEITURA" title="Input em inglês" description="Lições específicas verificadas nas páginas oficiais; dificuldade indicada pela fonte. Assistir, compreender e precisar repetir são registros diferentes." /><div className="input-banner"><Headphones size={22} /><div><b>Escuta ativa, sem traduzir palavra por palavra</b><span>Primeiro escute pela ideia geral; depois faça a preparação e os exercícios disponíveis na lição.</span></div><div className="input-filters"><label className="field-label" htmlFor="input-level">Dificuldade</label><select id="input-level" value={level} onChange={(event) => setLevel(event.target.value)}><option>Todos</option>{['A0', 'A0–A1', 'A1', 'A2', 'A2–B1', 'B1'].map((item) => <option key={item}>{item}</option>)}</select><label className="field-label" htmlFor="input-skill">Habilidade</label><select id="input-skill" value={skill} onChange={(event) => setSkill(event.target.value)}><option>Todas</option>{['Listening', 'Reading', 'Listening + speaking'].map((item) => <option key={item}>{item}</option>)}</select><label className="field-label" htmlFor="input-topic">Tema</label><select id="input-topic" value={topic} onChange={(event) => setTopic(event.target.value)}><option>Todos</option>{['Introductions', 'Everyday life', 'Work', 'Study', 'Story'].map((item) => <option key={item}>{item}</option>)}</select></div></div><div className="resource-grid">{resources.map((item) => { const progress = data.inputProgress?.[item.id] || { watched: false, understood: false, repeat: false, updatedAt: '' }; const valid = isTrustedResourceUrl(item.url); return <Card className="resource-card" key={item.id}><div className="resource-card-top"><span className="resource-icon"><BookOpen size={18} /></span><span className="level-pill">{item.level}</span></div><span className="eyebrow">{item.topic}</span><h3>{item.title}</h3><p>{item.source} · {item.skill}</p><p><b>Objetivo:</b> {item.objective}</p><p><b>Exercício:</b> {item.exercise}</p><a className="text-link" href={item.url} target="_blank" rel="noopener noreferrer">Abrir lição original <ArrowRight size={14} /></a>{!valid && <small role="alert">Link requer revisão antes de usar.</small>}<div className="resource-progress"><label><input type="checkbox" checked={progress.watched} onChange={(event) => setState(item.id, 'watched', event.target.checked)} /> Assisti</label><label><input type="checkbox" checked={progress.understood} onChange={(event) => setState(item.id, 'understood', event.target.checked)} /> Compreendi</label><label><input type="checkbox" checked={progress.repeat} onChange={(event) => setState(item.id, 'repeat', event.target.checked)} /> Preciso repetir</label></div>{progress.updatedAt && <small className="subtle">Progresso salvo localmente</small>}</Card>; })}</div>{resources.length === 0 && <p className="empty-copy">Nenhuma lição corresponde a esses filtros.</p>}<Card className="media-note"><SectionTitle>Fontes e critério</SectionTitle><p>Os links abrem lições oficiais com título e tema específicos; cada item propõe um objetivo e exercício. Assistir não significa compreensão: os três controles são independentes.</p><div className="note-chips"><span>1 · Ouça pela ideia geral</span><span>2 · Faça os exercícios da fonte</span><span>3 · Marque compreensão à parte</span></div></Card></>;
}

function Speaking({ data, update, showNotice }: { data: AppData; update: (fn: (current: AppData) => AppData) => void; showNotice: (message: string) => void }) {
  const [selected, setSelected] = useState(0); const [minutes, setMinutes] = useState(10); const [notes, setNotes] = useState(''); const [recording, setRecording] = useState(false); const [audioUrl, setAudioUrl] = useState(''); const recorder = useRef<MediaRecorder | null>(null); const chunks = useRef<Blob[]>([]); const scenario = conversationScenarios[selected];
  useEffect(() => () => { if (audioUrl) URL.revokeObjectURL(audioUrl); recorder.current?.stream.getTracks().forEach((track) => track.stop()); }, [audioUrl]);
  const copyPrompt = async () => { await navigator.clipboard?.writeText(chatGPTVoicePrompt(scenario)); showNotice('Prompt copiado. Cole no ChatGPT Voice quando quiser.'); };
  const record = async () => { try { const stream = await navigator.mediaDevices.getUserMedia({ audio: true }); const instance = new MediaRecorder(stream); recorder.current = instance; chunks.current = []; instance.ondataavailable = (event) => { if (event.data.size) chunks.current.push(event.data); }; instance.onstop = () => { if (audioUrl) URL.revokeObjectURL(audioUrl); setAudioUrl(URL.createObjectURL(new Blob(chunks.current, { type: 'audio/webm' }))); stream.getTracks().forEach((track) => track.stop()); }; instance.start(); setRecording(true); } catch { showNotice('Microfone não disponível ou permissão negada. Você ainda pode registrar por escrito.'); } };
  const stop = () => { recorder.current?.stop(); setRecording(false); };
  const saveSession = () => { update((current) => ({ ...current, speaking: [{ date: new Date().toISOString(), topic: scenario.title, minutes, notes }, ...current.speaking] })); setNotes(''); showNotice('Prática registrada. O áudio não é enviado nem salvo pelo app.'); };
  return <><PageHeading eyebrow="PRODUÇÃO ORAL" title="Vamos conversar" description="Roleplays em progressão desde A0. Copie o roteiro para o ChatGPT Voice gratuito ou grave localmente com sua permissão." /><div className="speaking-layout"><div><Card className="roleplay-card"><div className="card-topline"><span>ROLEPLAY {String(selected + 1).padStart(2, '0')}</span><span className="subtle">{scenario.level} · Português → English</span></div><select aria-label="Selecionar roleplay" value={selected} onChange={(event) => setSelected(Number(event.target.value))}>{conversationScenarios.map((role, index) => <option key={role.id} value={index}>{role.level} · {role.title}</option>)}</select><h2>{scenario.title}</h2><p><b>Objetivo:</b> {scenario.goal}</p><p>{scenario.prompt}</p><div className="phrase-list">{scenario.phrases.map((phrase) => <span key={phrase}>{phrase}</span>)}</div><p><b>Critérios para tentar:</b> {scenario.success.join(' · ')}</p><Button onClick={() => void copyPrompt()}><Sparkles size={16} /> Copiar prompt para ChatGPT Voice</Button><small className="privacy-note">Professor com IA próprio: arquitetura preparada por interface de provedor, ainda sem serviço conectado ou chave. Nenhuma resposta de IA é simulada neste app.</small></Card><Card><SectionTitle>Registre a prática</SectionTitle><label className="field-label" htmlFor="speaking-minutes">Minutos praticados</label><input id="speaking-minutes" type="number" min="1" max="180" value={minutes} onChange={(event) => setMinutes(Number(event.target.value))} /><label className="field-label" htmlFor="speaking-notes">Notas ou feedback manual</label><textarea id="speaking-notes" value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Que frase você conseguiu dizer? Que som quer praticar?" rows={3} />{audioUrl && <audio controls src={audioUrl} className="audio-preview">Seu navegador não suporta áudio.</audio>}<div className="form-actions">{recording ? <Button variant="secondary" onClick={stop}><span className="record-dot" /> Parar gravação</Button> : <Button variant="secondary" onClick={() => void record()}><Mic2 size={16} /> Gravar aqui</Button>}<Button onClick={saveSession}>Salvar sessão <Check size={15} /></Button></div><small className="privacy-note">A gravação só existe na memória desta página e não é sincronizada.</small></Card></div><div><Card className="speaking-tip"><div className="output-icon"><Mic2 size={19} /></div><span className="eyebrow">SEM PRESSA</span><h3>Fale antes de tentar traduzir tudo.</h3><p>Use as frases de apoio. Pausas e erros fazem parte da prática — registre uma evidência, não uma nota de fluência.</p></Card><Card><SectionTitle>Práticas recentes</SectionTitle>{data.speaking.length ? data.speaking.slice(0, 6).map((item, index) => <div className="recent-item" key={`${item.date}-${index}`}><b>{item.topic}</b><small>{format(parseISO(item.date), 'd MMM, HH:mm', { locale: ptBR })} · {item.minutes} min</small>{item.notes && <p>{item.notes}</p>}</div>) : <p className="empty-copy">Suas sessões aparecerão aqui quando você as registrar.</p>}</Card></div></div></>; }

function Review({ data, update }: { data: AppData; update: (fn: (current: AppData) => AppData) => void }) {
  const [showAnswer, setShowAnswer] = useState(false); const [phrase, setPhrase] = useState(''); const [example, setExample] = useState(''); const [meaning, setMeaning] = useState(''); const [topic, setTopic] = useState<'cotidiano' | 'startup'>('cotidiano'); const due = dueCards(data); const current = due[0];
  const grade = (choice: 'easy' | 'hard') => { if (!current) return; update((old) => ({ ...old, cards: old.cards.map((card) => card.id === current.id ? scheduleReview(card, choice) : card) })); setShowAnswer(false); };
  const addCard = () => { if (!phrase.trim() || !example.trim() || !meaning.trim()) return; const card: ReviewCard = { id: crypto.randomUUID(), phrase: phrase.trim(), example: example.trim(), meaning: meaning.trim(), topic, interval: 0, ease: 2.3, dueDate: todayISO() }; update((old) => ({ ...old, cards: [...old.cards, card] })); setPhrase(''); setExample(''); setMeaning(''); };
  return <><PageHeading eyebrow="MEMÓRIA DE LONGO PRAZO" title="Revisão espaçada" description="Crie seus próprios cartões com frases contextualizadas. A próxima revisão progride por D+1, D+3, D+7, D+14 e D+30." /><div className="review-overview"><div><span className="eyebrow">VENCIDOS HOJE</span><b>{due.length}</b></div><div><span className="eyebrow">TOTAL DE CARTÕES</span><b>{data.cards.length}</b></div><div><span className="eyebrow">PRÓXIMO INTERVALO</span><b>D+1 → D+3 → D+7</b></div></div><div className="review-layout"><Card className="flashcard-panel"><SectionTitle detail={<span className="subtle">{due.length ? `${due.length} na fila` : 'Fila em dia'}</span>}>Pratique lembrar</SectionTitle>{current ? <div className="flashcard"><span className="topic-pill">{current.topic}</span><h2>{current.phrase}</h2>{showAnswer ? <div className="flash-answer"><p>{current.example}</p><span>{current.meaning}</span></div> : <p>Tente lembrar o significado e um exemplo antes de revelar.</p>}<Button variant="secondary" onClick={() => setShowAnswer((value) => !value)}>{showAnswer ? 'Ocultar resposta' : 'Revelar resposta'}</Button>{showAnswer && <div className="grade-buttons"><Button variant="secondary" onClick={() => grade('hard')}>Difícil · rever amanhã</Button><Button onClick={() => grade('easy')}>Fácil · avançar intervalo</Button></div>}</div> : <div className="review-empty"><div className="empty-book"><Check size={24} /></div><h3>Nenhum cartão vencido</h3><p>Adicione uma frase própria para criar sua primeira revisão.</p></div>}</Card><Card className="new-card-panel"><SectionTitle>Adicionar cartão</SectionTitle><label className="field-label" htmlFor="card-phrase">Frase em inglês</label><input id="card-phrase" value={phrase} onChange={(event) => setPhrase(event.target.value)} placeholder="I work on a startup." /><label className="field-label" htmlFor="card-example">Exemplo em inglês</label><input id="card-example" value={example} onChange={(event) => setExample(event.target.value)} placeholder="I work on a startup called Tickrify." /><label className="field-label" htmlFor="card-meaning">Significado ou pista em português</label><input id="card-meaning" value={meaning} onChange={(event) => setMeaning(event.target.value)} placeholder="Trabalho em uma startup." /><label className="field-label" htmlFor="card-topic">Tema</label><select id="card-topic" value={topic} onChange={(event) => setTopic(event.target.value as 'cotidiano' | 'startup')}><option value="cotidiano">Cotidiano</option><option value="startup">Startup</option></select><Button onClick={addCard}><Plus size={15} /> Salvar cartão</Button></Card></div><Card><SectionTitle>Seus cartões</SectionTitle>{data.cards.length ? <div className="card-table">{data.cards.map((card) => <div className="card-row" key={card.id}><b>{card.phrase}</b><span>{card.meaning}</span><span className="due-date">Próxima: {card.dueDate}</span></div>)}</div> : <p className="empty-copy">Seus cartões aparecem nesta lista. O conteúdo é criado por você; nenhum vocabulário foi inserido sem contexto.</p>}</Card></>;
}

function Library() { const [level, setLevel] = useState('Todos'); const [skill, setSkill] = useState('Todas'); const resources = verifiedResources.filter((item) => (level === 'Todos' || item.level === level) && (skill === 'Todas' || item.skill === skill)); return <><PageHeading eyebrow="REFERÊNCIAS CURADAS" title="Biblioteca de inglês" description="Lições e materiais específicos de fontes oficiais, organizados pelo nível indicado pela publicação." /><div className="library-banner"><LibraryBig size={21} /><div><b>Escolha pelo nível informado na fonte</b><span>Para A0, use as lições iniciais; materiais A2–B1 e B1 são etapas futuras e podem exigir apoio.</span></div><label>Dificuldade<select aria-label="Filtrar biblioteca por dificuldade" value={level} onChange={(event) => setLevel(event.target.value)}><option>Todos</option>{['A0', 'A0–A1', 'A1', 'A2', 'A2–B1', 'B1'].map((item) => <option key={item}>{item}</option>)}</select></label><label>Habilidade<select aria-label="Filtrar biblioteca por habilidade" value={skill} onChange={(event) => setSkill(event.target.value)}><option>Todas</option>{['Listening', 'Reading', 'Listening + speaking'].map((item) => <option key={item}>{item}</option>)}</select></label></div><div className="library-list">{resources.map((item, index) => <Card className="library-row" key={item.id}><div className="library-number">{String(index + 1).padStart(2, '0')}</div><div className="library-info"><span className="eyebrow">{item.level} · {item.topic} · {item.skill}</span><h3>{item.source} · {item.title}</h3><p>{item.objective} {item.exercise}</p></div><a className="button secondary" href={item.url} target="_blank" rel="noopener noreferrer">Abrir lição <ArrowRight size={14} /></a></Card>)}</div>{resources.length === 0 && <p className="empty-copy">Nenhuma lição corresponde a esses filtros.</p>}<Card className="film-note"><div className="resource-icon"><CircleHelp size={18} /></div><div><b>Filmes e séries</b><p>Use como sugestão de prática por áudio/legendas apenas quando você já tiver acesso legal ao título. Disponibilidade de streaming depende do seu serviço e região.</p></div></Card></>; }

function Assessments({ data, update }: { data: AppData; update: (fn: (current: AppData) => AppData) => void }) {
  const [period, setPeriod] = useState('Semanal'); const [dimension, setDimension] = useState('Listening'); const [score, setScore] = useState(3); const [notes, setNotes] = useState('');
  const [answers, setAnswers] = useState<number[]>([]);
  const periods = ['Semanal', '28 dias', '56 dias', '84 dias', '112 dias', '140 dias', '182 dias'];
  const add = (event: FormEvent) => { event.preventDefault(); update((current) => ({ ...current, assessments: [{ date: new Date().toISOString(), period, dimension, score, notes }, ...current.assessments] })); setNotes(''); };
  const questions = [
    { prompt: 'You meet someone. Choose a simple introduction.', options: ['My name is Ana.', 'I name Ana.', 'Name my is Ana.'], answer: 0 },
    { prompt: 'Complete: I ___ from Brazil.', options: ['is', 'am', 'are'], answer: 1 },
    { prompt: 'Read: “Leo lives in São Paulo. He works at home.” Where does Leo work?', options: ['In London.', 'At home.', 'At school.'], answer: 1 },
    { prompt: 'Choose the question asking someone’s country.', options: ['How old is the book?', 'Where are you from?', 'What time is blue?'], answer: 1 },
  ];
  const submitDiagnostic = () => {
    if (questions.some((_, index) => !Number.isInteger(answers[index]))) return;
    const correct = answers.reduce((sum, answer, index) => sum + (answer === questions[index].answer ? 1 : 0), 0);
    const assessment = { id: crypto.randomUUID(), date: new Date().toISOString(), period: 'Diagnóstico inicial', dimension: 'Leitura e estruturas A0', score: Math.max(1, Math.round(correct / questions.length * 5)), correctAnswers: correct, totalQuestions: questions.length, answers, notes: `Acertos: ${correct}/${questions.length}. Diagnóstico curto de leitura e estruturas; não mede listening, fala ou certifica nível.` };
    update((current) => ({ ...current, assessments: [assessment, ...current.assessments] })); setAnswers([]);
  };
  const monthlyTask: Record<string, string> = { Listening: 'Escolha uma lição Input do seu nível. Faça a preparação, escute sem transcrição e registre ideia principal e dois detalhes.', Reading: 'Leia o trecho em inglês de uma atividade compatível com seu nível e escreva a ideia principal e duas informações explícitas.', Speaking: 'Responda ao roleplay do nível atual sem ler primeiro; depois marque quais critérios conseguiu cumprir.', Pitch: 'Explique problema, público e solução em frases adequadas ao seu nível. No início, use frases curtas e apoio.' };
  return <><PageHeading eyebrow="ACOMPANHE COMPETÊNCIAS" title="Avaliações" description="Diagnóstico curto com respostas verificáveis e avaliação mensal por evidência. Resultados são registros de aprendizagem, não certificação CEFR." /><div className="assessment-grid">{['Listening', 'Reading', 'Speaking', 'Pitch'].map((label, index) => <Card className="assessment-skill" key={label}><div className={`skill-illustration skill-${index}`}><span>{['♫', 'Aa', '◖', '↗'][index]}</span></div><span className="eyebrow">HABILIDADE</span><h3>{label}</h3><p>{data.assessments.find((record) => record.dimension === label)?.notes || 'Ainda sem evidência registrada.'}</p><span className="subtle">{data.assessments.find((record) => record.dimension === label) ? `Último registro: nota ${data.assessments.find((record) => record.dimension === label)?.score}/5` : 'Sem avaliação'}</span></Card>)}</div><div className="assessment-layout"><Card><SectionTitle>Diagnóstico inicial · leitura e estruturas</SectionTitle><p>Responda sem consultar material. Este teste curto não mede compreensão auditiva ou pronúncia; as outras habilidades têm avaliações próprias por tarefa e evidência.</p><div className="diagnostic-questions">{questions.map((question, index) => <fieldset key={question.prompt}><legend>{index + 1}. {question.prompt}</legend>{question.options.map((option, optionIndex) => <label key={option}><input type="radio" name={`diagnostic-${index}`} checked={answers[index] === optionIndex} onChange={() => setAnswers((old) => { const next = [...old]; next[index] = optionIndex; return next; })} /> {option}</label>)}</fieldset>)}</div><Button onClick={submitDiagnostic} disabled={questions.some((_, index) => !Number.isInteger(answers[index]))}>Salvar resultado do diagnóstico</Button></Card><Card><SectionTitle>Avaliação mensal e semanal</SectionTitle><p className="assessment-prompt"><b>Tarefa sugerida:</b> {monthlyTask[dimension]}</p><form onSubmit={add}><label className="field-label" htmlFor="assess-period">Marco</label><select id="assess-period" value={period} onChange={(event) => setPeriod(event.target.value)}>{periods.map((item) => <option key={item}>{item}</option>)}</select><label className="field-label" htmlFor="assess-dimension">Habilidade</label><select id="assess-dimension" value={dimension} onChange={(event) => setDimension(event.target.value)}>{['Listening', 'Reading', 'Speaking', 'Pitch'].map((item) => <option key={item}>{item}</option>)}</select><label className="field-label" htmlFor="assess-score">Rubrica baseada no que você conseguiu fazer (1 = ainda difícil, 5 = confortável)</label><input id="assess-score" type="range" min="1" max="5" value={score} onChange={(event) => setScore(Number(event.target.value))} /><div className="score-markers"><span>1</span><b>{score}</b><span>5</span></div><label className="field-label" htmlFor="assess-notes">Evidência concreta</label><textarea id="assess-notes" required value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="O que entendeu ou conseguiu dizer? Qual foi o material e qual ponto quer tentar novamente?" rows={3} /><Button type="submit">Salvar avaliação <Check size={15} /></Button></form></Card></div><Card><SectionTitle>Histórico persistente</SectionTitle>{data.assessments.length ? <div className="card-table">{data.assessments.map((item, index) => <div className="assessment-row" key={item.id || `${item.date}-${index}`}><div><b>{item.dimension} · {item.period}</b><small>{format(parseISO(item.date), "d 'de' MMMM, yyyy", { locale: ptBR })}</small></div><span className="assessment-score">{item.score}<small>/5{item.totalQuestions ? ` · ${item.correctAnswers}/${item.totalQuestions}` : ''}</small></span><p>{item.notes}</p></div>)}</div> : <p className="empty-copy">Faça o diagnóstico ou registre sua primeira avaliação.</p>}</Card></>;
}

function Statistics({ data, doneCount, completedDays }: { data: AppData; doneCount: number; completedDays: number }) {
  const totalMinutes = days.flatMap((day) => makeDailyPlan(day.day, data)).reduce((sum, task) => { const record = data.activities[task.key]; return sum + (record?.status === 'done' ? record.actualMinutes ?? task.minutes : 0); }, 0);
  const byType = days.flatMap((day) => makeDailyPlan(day.day, data).map((task) => ({ type: task.kind, record: data.activities[task.key] }))).reduce<Record<string, number>>((counts, item) => { if (item.record?.status === 'done') counts[item.type] = (counts[item.type] || 0) + 1; return counts; }, {});
  const exportFile = (type: 'json' | 'csv') => { const content = type === 'json' ? JSON.stringify({ exportedAt: new Date().toISOString(), curriculum: seed.metadata, progress: data }, null, 2) : ['date,day,task,status,planned_minutes', ...Object.entries(data.activities).map(([key, value]) => { const [dayNumber] = key.split(':').map(Number); const task = makeDailyPlan(dayNumber, data).find((item) => item.key === key); return `${days[dayNumber - 1]?.date || ''},${dayNumber},"${task?.title.replaceAll('"', '""') || ''}",${value.status},${value.status === 'done' ? value.actualMinutes ?? task?.minutes ?? '' : ''}`; })].join('\n'); const blob = new Blob([content], { type: type === 'json' ? 'application/json' : 'text/csv' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `english-os-progresso.${type}`; a.click(); URL.revokeObjectURL(url); };
  const best = Object.entries(byType).sort((a, b) => b[1] - a[1])[0];
  const skillLabels: Record<string, string> = { listening: 'Compreensão oral', reading: 'Leitura', speaking: 'Conversação', writing: 'Escrita', vocabulary: 'Vocabulário', grammar: 'Gramática', startup: 'Startup English' };
  const evidencedSkills = (Object.keys(skillLabels) as SkillId[]).filter((skill) => skillRetention(data.skillAttempts || [], skill).attempts > 0);
  return <><PageHeading eyebrow="DADOS DO SEU ESTUDO" title="Estatísticas" description="Horas e atividades só contam quando você registra. Conclusão mede consistência de estudo, não fluência." ><Button variant="secondary" onClick={() => exportFile('csv')}><ArrowDownToLine size={15} /> Exportar CSV</Button><Button variant="secondary" onClick={() => exportFile('json')}><ArrowDownToLine size={15} /> JSON</Button></PageHeading><div className="stats-row statistics-top"><StatCard icon={<Clock3 size={18} />} label="Carga concluída (estimada)" value={`${Math.floor(totalMinutes / 60)}h ${totalMinutes % 60}m`} helper="tempo planejado das etapas marcadas; não cronometrado" /><StatCard icon={<Check size={18} />} label="Atividades concluídas" value={String(doneCount)} helper="nas 182 datas do currículo" /><StatCard icon={<CalendarDays size={18} />} label="Dias completos" value={`${completedDays} / 182`} helper="todas as etapas marcadas" /></div><div className="content-grid"><Card className="skill-chart"><SectionTitle>Atividades por área</SectionTitle>{[['udemy', 'Udemy'], ['input', 'Input'], ['speaking', 'Conversação'], ['review', 'Revisão'], ['writing', 'Escrita'], ['vocabulary', 'Vocabulário'], ['quiz', 'Testes'], ['startup', 'Startup English']].map(([key, label]) => <div className="bar-row" key={key}><span>{label}</span><ProgressBar value={byType[key] ? byType[key] / Math.max(doneCount, 1) * 100 : 0} /><b>{byType[key] || 0}</b></div>)}{!doneCount && <p className="empty-copy">Os gráficos ganham forma conforme você registra seu estudo.</p>}</Card><Card className="streak-card"><div className="streak-circle"><span>{completedDays}</span><small>dias</small></div><span className="eyebrow">DIAS COMPLETOS</span><h3>{completedDays ? 'Boa continuidade' : 'Seu caminho começa amanhã'}</h3><p>{best ? `Sua área mais praticada é ${best[0]}.` : 'Uma atividade marcada já conta como progresso real.'}</p><div className="streak-foot">Plano de 26 semanas · America/Sao_Paulo</div></Card></div><Card className="skill-evidence"><SectionTitle detail={<span className="subtle">Resultados de testes objetivos salvos</span>}>Evidência por habilidade</SectionTitle>{evidencedSkills.length ? evidencedSkills.map((skill) => { const evidence = skillRetention(data.skillAttempts || [], skill); const status = data.skills?.[skill]?.status; return <div className="bar-row" key={skill}><span>{skillLabels[skill]} · {evidence.attempts} tentativa(s)</span><ProgressBar value={evidence.percent} /><b>{evidence.percent}%</b><small>{evidence.correct}/{evidence.total} acertos · {status === 'mastered' ? 'consistente em datas distintas' : status === 'reviewing' ? 'revisão sugerida' : 'em observação'}</small></div>; }) : <p className="empty-copy">Ainda não há resultados objetivos por habilidade. Marcar aulas ou atividades não altera este painel; corrija os testes diários para criar evidências.</p>}<p className="subtle">Percentuais resumem apenas questões respondidas no English OS; não equivalem a uma certificação CEFR nem avaliam fala espontânea.</p></Card><Card><SectionTitle>Continuidade recente</SectionTitle><div className="activity-heatmap">{days.map((day) => { const status = dayPlanStatus(day.day, data, todayISO()); return <div key={day.day} title={`Dia ${day.day}: ${status}`} className={`heat-cell heat-${status}`} />; })}</div><div className="heat-legend"><span>Sem atividade</span><i /><span>Em andamento</span><i className="heat-full" /><span>Dia completo</span></div></Card></>;
}

function SettingsPage({ data, update, showNotice }: { data: AppData; update: (fn: (current: AppData) => AppData) => void; showNotice: (message: string) => void }) {
  const [email, setEmail] = useState(''); const [cloudStatus, setCloudStatus] = useState('');
  const fileRef = useRef<HTMLInputElement>(null);
  const exportAll = () => { const blob = new Blob([JSON.stringify({ format: 'english-os-backup', formatVersion: 1, exportedAt: new Date().toISOString(), curriculumSeedVersion: 1, progress: data }, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `english-os-backup-${todayISO()}.json`; document.body.append(a); a.click(); a.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); };
  const importAll = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; try { if (file.size > 20 * 1024 * 1024) throw new Error('Backup acima de 20 MB; confira o arquivo antes de importar.'); const parsed: unknown = JSON.parse(await file.text()); const merged = mergeBackupData(data, parsed); update(() => merged); showNotice('Backup combinado; histórico local e catálogo do arquivo foram preservados.'); } catch (error) { showNotice(error instanceof Error ? error.message : 'Arquivo inválido.'); } event.target.value = ''; };
  const sendLink = async (event: FormEvent) => { event.preventDefault(); if (!cloudConfigured) return setCloudStatus('Configure VITE_SUPABASE_URL e VITE_SUPABASE_ANON_KEY no arquivo .env.'); const { supabase: client } = await import('../cloud'); const { error } = await client!.auth.signInWithOtp({ email, options: { emailRedirectTo: new URL(import.meta.env.BASE_URL, window.location.origin).href } }); setCloudStatus(error ? error.message : 'Confira seu email para entrar pelo link enviado pelo Supabase.'); };
  const cloudSync = async () => {
    try {
      const { pullCloud: pull, pushCloud: push } = await import('../cloud');
      const remote = await pull();
      if (remote) {
        const merged = mergeProgress(data, remote);
        update(() => merged); await push(merged); setCloudStatus('Progresso local e remoto combinados e sincronizados. Dados permanecem neste dispositivo.');
      } else { await push(data); setCloudStatus('Backup inicial salvo na sua conta Supabase.'); }
    } catch (error) { setCloudStatus(error instanceof Error ? error.message : 'Não foi possível sincronizar.'); }
  };
  const deleteAll = async () => { if (!window.confirm('Apagar todo o progresso local, aulas importadas, cartões e avaliações? Esta ação não pode ser desfeita.')) return; await clearData(); window.location.reload(); };
  const settingsItems = [
    { title: 'Data de início', detail: 'Reorganiza as 182 datas planejadas; temas e histórico permanecem.', right: <input aria-label="Data de início" type="date" value={data.settings.startDate} onChange={(event) => update((current) => ({ ...current, settings: { ...current.settings, startDate: event.target.value || current.settings.startDate } }))} /> },
    { title: 'Carga de estudo', detail: 'Meta de 30–180 min nos dias cheios; o dia semanal de descanso ativo preserva até 45 min.', right: <input aria-label="Minutos em dia cheio" type="number" min="30" max="180" step="15" value={Math.max(30, Math.min(180, data.settings.targetMinutes))} onChange={(event) => update((current) => ({ ...current, settings: { ...current.settings, targetMinutes: Math.max(30, Math.min(180, Number(event.target.value) || 120)) } }))} /> },
    { title: 'Fuso horário', detail: 'As datas base foram planejadas para este fuso.', right: <input readOnly aria-label="Fuso horário" value={data.settings.timezone} /> },
    { title: 'Nível de partida', detail: 'A progressão temática original continua preservada.', right: <select aria-label="Nível de partida" value={data.settings.level} onChange={(event) => update((current) => ({ ...current, settings: { ...current.settings, level: event.target.value } }))}><option>A0</option><option>A1</option><option>A2</option></select> },
  ];
  return <><PageHeading eyebrow="SEU DISPOSITIVO E SUA CONTA" title="Configurações" description="Seus dados de estudo permanecem no dispositivo por padrão. Exporte um backup com frequência." /><Card className="settings-card"><SectionTitle>Preferências do plano</SectionTitle>{settingsItems.map((item) => <div className="setting-row" key={item.title}><div><b>{item.title}</b><small>{item.detail}</small></div><span>{item.right}</span></div>)}</Card><div className="settings-grid"><Card><SectionTitle>Backup e privacidade</SectionTitle><p className="settings-copy">Suas marcações, notas, cartões e avaliações ficam neste perfil do navegador. Exporte um backup JSON para migrar entre Safari, Chrome, computador ou endereço local e publicado.</p><div className="form-actions"><Button variant="secondary" onClick={exportAll}><ArrowDownToLine size={15} /> Exportar backup</Button><Button variant="secondary" onClick={() => fileRef.current?.click()}><Upload size={15} /> Importar backup</Button><input ref={fileRef} type="file" accept=".json,application/json" hidden onChange={importAll} /></div><Button variant="quiet" className="delete-button" onClick={() => void deleteAll()}>Apagar todo o progresso local</Button></Card><Card><SectionTitle detail={<span className={`cloud-tag ${cloudConfigured ? 'ready' : ''}`}><span className="status-led" />{cloudConfigured ? 'Variáveis detectadas' : 'Opcional'}</span>}>Sincronização Supabase</SectionTitle><p className="settings-copy">Sincronização requer URL, chave pública anon, migrations aplicadas e autenticação por email habilitada no seu projeto.</p>{!cloudConfigured ? <ol className="setup-list"><li>Crie um projeto Supabase e habilite autenticação por link de email.</li><li>Copie <b>Project URL</b> e a chave <b>anon/public</b> do painel.</li><li>Preencha os valores no arquivo <code>.env</code> com base no <code>.env.example</code>.</li><li>Revise e aplique <code>supabase/migrations/001_init.sql</code> para ativar a sincronização; reinicie <code>npm run dev</code>.</li><li>Tutor IA é opcional: requer Edge Function, migration <code>002_ai_tutor_usage_limits.sql</code>, chave de provedor no Secret Manager do Supabase e <code>VITE_AI_TUTOR_URL</code>. Veja o README; o provedor pode cobrar.</li></ol> : <form onSubmit={(event) => void sendLink(event)} className="cloud-form"><label className="field-label" htmlFor="cloud-email">Seu email</label><input id="cloud-email" type="email" required value={email} onChange={(event) => setEmail(event.target.value)} placeholder="voce@exemplo.com" /><div className="form-actions"><Button type="submit" variant="secondary"><Cloud size={15} /> Enviar link de acesso</Button><Button type="button" onClick={() => void cloudSync()}><Cloud size={15} /> Sincronizar agora</Button></div></form>}{cloudStatus && <p className="cloud-status-message" role="status">{cloudStatus}</p>}<div className="security-note">Nunca cole senha de banco, service_role ou chave secreta em arquivos VITE_. A anon key é pública; políticas RLS protegem cada registro.</div></Card></div><div className="acceptance-note"><CircleHelp size={15} /><span>Dados armazenados e backup exportável. O Supabase é opcional; o tutor IA só funciona após configuração autenticada; não há upload de gravações.</span></div></>;
}
